/** Immutable lookup assets generated with Python standard codecs (Shift-JIS and GB2312).
 * Each entry is [Unicode BMP codepoint (uint16), QR double-byte code (uint16)].
 * These are data tables, not the original Python encoder code. Lazy decoded once.
 */
const KANJI_TABLE = ''; // 6879 characters
const HANZI_TABLE = ''; // 7445 characters
const caches = new Map();
function decodeTable(id, src) {
  if (!caches.has(id)) {
    const bytes = atob(src), map = new Map();
    for(let i=0;i<bytes.length;i+=4) map.set((bytes.charCodeAt(i)<<8)|bytes.charCodeAt(i+1),(bytes.charCodeAt(i+2)<<8)|bytes.charCodeAt(i+3));
    caches.set(id,map);
  }
  return caches.get(id);
}
export function unicodeKanjiCode(char){return decodeTable('kanji',KANJI_TABLE).get(char.codePointAt(0))??null;}
export function unicodeHanziCode(char){return decodeTable('hanzi',HANZI_TABLE).get(char.codePointAt(0))??null;}
